#!/usr/bin/env python3
from pathlib import Path
import sys

root = Path(sys.argv[1] if len(sys.argv) > 1 else ".").resolve()
matches = list(root.rglob("app/src/main/assets/www/index.html"))
if len(matches) != 1:
    raise SystemExit(f"Expected one game index.html, found {len(matches)}")
html = matches[0]
source = html.read_text(encoding="utf-8")
marker = "BATTLEZONE_V6_EDGE_CONTROL_SYSTEM_V3"
css_name = "v6-edge-control-system.css"
link = f'<link rel="stylesheet" href="./css/{css_name}">'
if marker not in source:
    if source.count("</head>") != 1:
        raise SystemExit("Expected one closing head tag")
    source = source.replace("</head>", link + "\n</head>", 1)
    source = source.replace("</body>", f"<!-- {marker} -->\n</body>", 1)
